package cn.bidcheck.verification;

import cn.bidcheck.domain.Domain.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class PricingVerificationTest {
    final PricingVerification pricing=new PricingVerification();
    static String formula(){return PricingVerification.TEMPLATE.replace("{discount}","5").replace("{threshold}","5").replace("{below}","5").replace("{factor}","95").replace("{upper}","1").replace("{maxHigh}","60").replace("{upperFormula}","1").replace("{lower}","0.5").replace("{maxLow}","60").replace("{lowerFormula}","0.5");}
    static Evidence evidence(String text){return new Evidence("source","原始记录.pdf",1,"PAGE",text,"p1",1);}
    static Checkpoint cp(String text){return new Checkpoint("price-rule","价格评分","评分","","SEMANTIC_RESPONSE","scoring","",text,"",false,true,true,evidence(formula()));}
    Map<String,Object> input(String... prices){List<Map<String,Object>> rows=new ArrayList<>();for(int i=0;i<prices.length;i++)rows.add(new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("bidder", "合成企业"+i, "price", prices[i], "evidence", evidence("本项目合成企业"+i+"经算术修正后不含税投标价："+prices[i]+"元"))));return new LinkedHashMap<>(cn.bidcheck.compat.Java8Api.mapOf("confirmed", true, "rosterComplete", true, "arithmeticCorrectionsConfirmed", true, "taxBasis", "EXCLUDING_TAX", "targetBidder", "合成企业0", "entries", rows, "rosterEvidence", evidence("本项目全部有效投标人报价名单已确认")));}
    Map<String,Object> evaluate(Map<String,Object> data){return pricing.evaluate(cp(formula()),cn.bidcheck.compat.Java8Api.mapOf("pricingData", data)).orElseThrow(java.util.NoSuchElementException::new);}
    Map<?,?> proof(Map<String,Object> result){return (Map<?,?>)result.get("proof");}
    boolean gap(Map<String,Object> result,String code){return ((List<?>)result.get("gaps")).stream().anyMatch(g->code.equals(((Map<?,?>)g).get("code")));}
    @Test void fewerThanFiveKeepAllAndCalculateAboveBenchmark(){java.util.Map<java.lang.String, java.lang.Object> r=evaluate(input("100","100","100","100"));assertEquals("PASS",r.get("businessDecision"));assertEquals("54.74",proof(r).get("score"));assertEquals("95",proof(r).get("benchmarkA"));assertEquals(4,proof(r).get("usedBidderCount"));assertEquals(cn.bidcheck.compat.Java8Api.listOf(),proof(r).get("excludedRecords"));assertEquals(false,r.get("officialReviewScore"));}
    @Test void trimExactlyOneHighestAndOneLowestEvenWhenPricesTie(){java.util.Map<java.lang.String, java.lang.Object> r=evaluate(input("100","100","100","200","300"));assertEquals("49.47",proof(r).get("score"));assertEquals(3,proof(r).get("usedBidderCount"));List<?> excluded=(List<?>)proof(r).get("excludedRecords");assertEquals(2,excluded.size());assertEquals("合成企业0",((Map<?,?>)excluded.get(0)).get("bidder"));assertEquals("合成企业4",((Map<?,?>)excluded.get(1)).get("bidder"));assertEquals(3,((List<?>)proof(r).get("includedRecords")).size());}
    @Test void fiveEqualPricesAreFiveRecordsNotOneDistinctPrice(){java.util.Map<java.lang.String, java.lang.Object> r=evaluate(input("100","100","100","100","100"));assertEquals(5,proof(r).get("validBidderCount"));assertEquals(3,proof(r).get("usedBidderCount"));assertEquals("54.74",proof(r).get("score"));}
    @Test void equalityGetsMaximumAndLowerPriceUsesHalfPenalty(){assertEquals("60.00",proof(evaluate(input("95","105"))).get("score"));assertEquals("36.32",proof(evaluate(input("50","150"))).get("score"));}
    @Test void floorIsZeroAndFinalRoundingIsHalfUpWithoutIntermediateRounding(){Map<String,Object> x=input("1","1","100");x.put("targetBidder","合成企业2");assertEquals("0.00",proof(evaluate(x)).get("score"));assertEquals("50.00",proof(evaluate(input("104.50475","95.49525"))).get("score"));}
    @Test void missingRosterCorrectionAndTaxCannotProduceScore(){java.util.Map<java.lang.String, java.lang.Object> r=pricing.evaluate(cp(formula()),cn.bidcheck.compat.Java8Api.mapOf()).orElseThrow(java.util.NoSuchElementException::new);assertEquals("UNDETERMINED",r.get("businessDecision"));assertTrue(gap(r,"PRICING_ROSTER_INCOMPLETE"));assertTrue(gap(r,"PRICING_ARITHMETIC_CORRECTIONS_UNCONFIRMED"));assertTrue(gap(r,"PRICING_TAX_BASIS_REQUIRED"));assertFalse(proof(r).containsKey("score"));}
    @SuppressWarnings("unchecked") @Test void duplicateEnterpriseInvalidPriceAndMissingEvidenceAreRejected(){java.util.Map<java.lang.String, java.lang.Object> duplicate=input("100","110");((List<Map<String,Object>>)duplicate.get("entries")).get(1).put("bidder","合成企业0");assertTrue(gap(evaluate(duplicate),"PRICING_BIDDER_DUPLICATE_OR_INVALID"));java.util.Map<java.lang.String, java.lang.Object> noEvidence=input("100");((List<Map<String,Object>>)noEvidence.get("entries")).get(0).remove("evidence");assertTrue(gap(evaluate(noEvidence),"PRICING_PRICE_EVIDENCE_REQUIRED"));for(Object raw:cn.bidcheck.compat.Java8Api.listOf("0", "-1", "NaN", "1e3", 100.1)){java.util.Map<java.lang.String, java.lang.Object> invalid=input("100");((List<Map<String,Object>>)invalid.get("entries")).get(0).put("price",raw);assertTrue(gap(evaluate(invalid),"PRICING_PRICE_INVALID"));}}
    @Test void unrecognizedOrChangedFormulaNeverUsesDefaultParameters(){for(String text:cn.bidcheck.compat.Java8Api.listOf("价格评分由评委确定", formula().replace("95%","90%"), formula().replace("×0.5","×0.8"), formula()+"额外加10分")){java.util.Map<java.lang.String, java.lang.Object> r=pricing.evaluate(cp(text),cn.bidcheck.compat.Java8Api.mapOf("pricingData", input("100","100"))).orElseThrow(java.util.NoSuchElementException::new);assertEquals("UNDETERMINED",r.get("businessDecision"));assertTrue(gap(r,"PRICING_FORMULA_UNSUPPORTED"));}}
    @Test void nonPriceItemIsNotIntercepted(){Checkpoint ordinary=new Checkpoint("x","企业业绩评分","","","SEMANTIC_RESPONSE","","","每项合同2分","",true,true,true,evidence("每项合同2分"));assertTrue((!pricing.evaluate(ordinary,cn.bidcheck.compat.Java8Api.mapOf()).isPresent()));}
    @Test void incidentalPriceScoreMentionDoesNotReplaceMaterialCheck(){Checkpoint ordinary=new Checkpoint("x","评审索引完整性","","","MATERIAL_EXISTENCE","","","评审索引中必须列出价格评分指引","",true,true,true,evidence("评审索引中必须列出价格评分指引"));assertTrue((!pricing.evaluate(ordinary,cn.bidcheck.compat.Java8Api.mapOf()).isPresent()));}
    @SuppressWarnings("unchecked") @Test void explicitHistoricalContractCannotSubstituteForBidPrice(){java.util.Map<java.lang.String, java.lang.Object> data=input("100");((List<Map<String,Object>>)data.get("entries")).get(0).put("evidence",evidence("历史合同金额100元"));assertTrue(gap(evaluate(data),"PRICING_HISTORICAL_PRICE_REJECTED"));}
    @Test void originalPolicyTailKeepsMissingInputConditionalRatherThanPermanentBlock(){String suffix=" 本项属于评分条件，不能将未获取可得分材料自动当成资格否决。只依据实际材料说明满足情况、缺项及不确定性，不能仅凭索引“满足”给满分；专业评价及最终分数由评审确认。 当前报价分册、全部有效评标价和算术修正信息未提供，必须UNDETERMINED，不输出确定价格分，不用历史合同金额替代。";java.util.Map<java.lang.String, java.lang.Object> r=pricing.evaluate(cp(formula()+suffix),cn.bidcheck.compat.Java8Api.mapOf("pricingData", input("100","100"))).orElseThrow(java.util.NoSuchElementException::new);assertEquals("PASS",r.get("businessDecision"));assertEquals(false,r.get("officialReviewScore"));}
}
